def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my, opp = history[-1]
    opp_list = [h[1] for h in history]
    opp_def = opp_list.count('D')

    # Heavy defection: defect if opponent defects a lot
    if opp_def * 2 > n:
        return 'D'
    recent_len = min(10, n)
    recent_opp = opp_list[-recent_len:]
    if recent_opp.count('D') >= 5:
        return 'D'

    # Tit-for-Tat with forgiveness
    if opp == 'D':
        if my == 'D':
            return 'C'  # break cycle
        else:
            return 'D'  # retaliate
    else:
        # Opponent cooperated
        # Endgame probe: if we are in last 10 rounds and opponent never defected,
        # occasionally defect to test for non-retaliation.
        if n >= 90 and opp_def == 0:
            if rng.random() < 0.15:
                return 'D'
        return 'C'
